create or replace function public.emit_booking_domain_event() returns trigger language plpgsql security definer set search_path='' as $function$ declare v_type text; v_payload jsonb; v_guruba_user_id uuid; v_event_id uuid; begin if tg_op='INSERT' then v_type:='booking.created'; elsif old.status is distinct from new.status then v_type:='booking.status_changed'; elsif old.scheduled_at is distinct from new.scheduled_at then v_type:='booking.rescheduled'; else return new; end if; v_payload:=jsonb_build_object('booking_id',new.id,'user_id',new.user_id,'guruba_id',new.guruba_id,'status',new.status,'scheduled_at',new.scheduled_at,'previous_status',case when tg_op='UPDATE' then old.status else null end); insert into public.booking_events(booking_id,event_type,payload) values(new.id,v_type,v_payload); insert into public.domain_events(aggregate_type,aggregate_id,event_type,payload) values('booking',new.id,v_type,v_payload) returning id into v_event_id; insert into public.job_queue(job_type,payload,idempotency_key) values('booking_event',jsonb_build_object('event_id',v_event_id,'booking_id',new.id,'event_type',v_type),'domain-event:'||v_event_id::text) on conflict (idempotency_key) do nothing; select g.user_id into v_guruba_user_id from public.gurubas g where g.id=new.guruba_id; if tg_op='INSERT' and v_guruba_user_id is not null then insert into public.notifications(user_id,title,message,notification_type,metadata) values(v_guruba_user_id,'New booking request','A new booking request has been created.','booking',jsonb_build_object('booking_id',new.id,'event','booking.created')); elsif new.status='confirmed' then insert into public.notifications(user_id,title,message,notification_type,metadata) values(new.user_id,'Booking confirmed','Your booking has been confirmed.','booking',jsonb_build_object('booking_id',new.id,'event','booking.confirmed')); elsif new.status='cancelled' then insert into public.notifications(user_id,title,message,notification_type,metadata) values(new.user_id,'Booking cancelled','A booking has been cancelled.','warning',jsonb_build_object('booking_id',new.id,'event','booking.cancelled')); end if; return new; end; $function$;
